INSERT INTO repo_courses (course_id, title, domain, discipline, description, objectives, learning_outcomes, course_type, level, status) VALUES ('COURSE_001', 'Data Structures & Algorithms', 'Engineering & Technology', 'Computer Science', 'Introduces fundamental data structures and algorithms for representing, organizing, storing, retrieving, and processing data. The course covers linear and non-linear structures, searching, sorting, hashing, and analysis of algorithmic efficiency.', 'Develop competence in selecting, implementing, analysing, and evaluating data structures and algorithms for computational problems, with emphasis on correctness, efficiency, data representation, and trade-offs.', 'Implement common data structures and algorithms; analyse time and space requirements; select suitable structures and algorithms for stated problem requirements; compare alternative approaches; and evaluate correctness, efficiency, and implementation trade-offs.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_002', 'Discrete Mathematics', 'Engineering & Technology', 'Computer Science', 'Develops mathematical foundations for computing, including logic, proof, sets, relations, functions, combinatorics, and graphs. Emphasis is placed on formal reasoning and structures used to specify and analyse computing problems.', 'Develop mathematical reasoning and abstraction needed to formulate, analyse, and prove statements and structures relevant to computing.', 'Construct and evaluate logical statements; apply proof techniques; work with sets, relations, and functions; solve basic counting problems; and model and analyse relationships using graphs.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_003', 'Database Management Systems', 'Engineering & Technology', 'Computer Science', 'Introduces principles and techniques for modelling, storing, querying, updating, and managing structured data. Topics include data models, relational databases, SQL, normalization, transactions, concurrency, and database integrity.', 'Develop competence in designing database schemas, querying and manipulating data, and reasoning about integrity, normalization, transactions, and concurrent access.', 'Construct conceptual and relational data models; formulate SQL queries; normalize relational schemas; explain transaction properties and concurrency control; and evaluate database design choices.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_004', 'Operating Systems', 'Engineering & Technology', 'Computer Science', 'Introduces operating-system mechanisms for managing processes, threads, CPU scheduling, memory, storage, files, and system resources. The course develops an understanding of how operating systems provide controlled and efficient execution environments.', 'Develop understanding of operating-system abstractions and mechanisms and the ability to analyse resource-management and concurrency problems.', 'Explain process and thread management; compare CPU scheduling approaches; analyse synchronization and deadlock issues; explain virtual-memory mechanisms; and describe file-system organization and protection.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_005', 'Computer Architecture', 'Engineering & Technology', 'Computer Science', 'Introduces the organization and operation of digital computer systems from logic and instruction-set concepts through processors, memory hierarchies, pipelining, and input/output. Emphasis is placed on how architectural choices affect performance and system behavior.', 'Develop the ability to explain, analyse, and evaluate computer organization and architectural mechanisms across the instruction, processor, memory, and I/O levels.', 'Explain basic digital and processor organization; interpret instruction-set features; analyse pipeline operation and hazards; evaluate memory hierarchy mechanisms; and describe I/O organization and interfaces.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_006', 'Design and Analysis of Algorithms', 'Engineering & Technology', 'Computer Science', 'Develops systematic methods for designing algorithms and analysing their correctness, time and space complexity, and applicability. Topics include divide-and-conquer, dynamic programming, greedy methods, graph algorithms, and computational complexity.', 'Develop competence in designing, analysing, proving, comparing, and selecting algorithms for computational problems.', 'Apply divide-and-conquer and dynamic-programming techniques; design greedy solutions; analyse graph algorithms; assess complexity; and recognize and reason about NP-complete problems.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_007', 'Software Engineering', 'Engineering & Technology', 'Computer Science', 'Introduces disciplined approaches to software development, covering lifecycle processes, requirements, modelling, architecture and design, agile development, testing, and software quality. Emphasis is placed on engineering software systematically under stated requirements and constraints.', 'Develop competence in specifying, designing, implementing, testing, and managing software systems using systematic engineering practices.', 'Describe software lifecycle models; elicit and specify requirements; model and design software systems; apply agile development practices; and plan and evaluate software testing activities.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_008', 'Computer Networks', 'Engineering & Technology', 'Computer Science', 'Introduces the principles and layered architecture of computer networks, including physical transmission, data-link protocols, internetworking, transport services, and application protocols. The course examines how data is communicated reliably and efficiently across interconnected systems.', 'Develop understanding of network architectures and protocols and the ability to analyse communication, addressing, routing, transport, and application mechanisms.', 'Explain layered network operation; describe transmission and framing mechanisms; configure and analyse IP addressing and routing; compare transport protocols; and explain common application-layer services.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_009', 'Mechanics of Materials', 'Engineering & Technology', 'Civil Engineering', 'Introduces the behaviour of deformable engineering materials under axial load, bending, shear, torsion, and combined loading. The course relates stresses, strains, material properties, and structural response to engineering analysis and design.', 'Develop the ability to determine stresses, strains, deformations, and strength-related responses of structural members subjected to common loading conditions.', 'Apply stress-strain relationships; calculate axial, bending, shear, and torsional stresses; determine beam deflections; and interpret structural response using appropriate mechanics principles.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_010', 'Fluid Mechanics', 'Engineering & Technology', 'Civil Engineering', 'Introduces the fundamental properties and behaviour of fluids at rest and in motion, including pressure, buoyancy, conservation laws, viscous flow, and internal pipe flow. The course develops analytical tools for fluid-system analysis.', 'Develop the ability to apply fluid-mechanics principles to analyse pressure forces, flow kinematics, conservation laws, and fluid flow through engineering systems.', 'Determine fluid properties and hydrostatic forces; apply continuity and energy principles; interpret flow regimes using dimensionless parameters; analyse internal flow; and relate governing equations to engineering applications.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_011', 'Structural Analysis I', 'Engineering & Technology', 'Civil Engineering', 'Introduces methods for analysing determinate and indeterminate structures, including internal forces, deflections, energy methods, and influence lines. The course develops the analytical basis for assessing structural response under static loading.', 'Develop competence in idealizing structures and determining reactions, internal forces, deflections, and response quantities using appropriate structural-analysis methods.', 'Analyse determinate structures; calculate structural deflections; apply energy and virtual-work methods; construct influence lines; and apply methods for selected indeterminate structures.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_012', 'Geotechnical Engineering', 'Engineering & Technology', 'Civil Engineering', 'Introduces the engineering behaviour of soils, including classification, permeability, consolidation, shear strength, and earth pressure. The course develops methods for evaluating soil properties and their implications for geotechnical engineering.', 'Develop the ability to characterize soil behaviour and apply geotechnical principles to seepage, settlement, shear resistance, and lateral earth pressure problems.', 'Classify soils using index properties; determine permeability; analyse consolidation and settlement; evaluate shear strength using appropriate criteria; and estimate earth pressures for geotechnical systems.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_013', 'Environmental Engineering', 'Engineering & Technology', 'Civil Engineering', 'Introduces engineering principles for water supply, water and wastewater treatment, wastewater collection, sewage treatment, and solid-waste management. Emphasis is placed on protecting public health and environmental quality through treatment and resource-management processes.', 'Develop competence in analysing environmental engineering systems for water demand, treatment, wastewater management, and solid-waste handling.', 'Estimate water demand; explain and evaluate water-treatment processes; describe wastewater collection and treatment systems; and identify appropriate approaches for solid-waste management.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_014', 'Transportation Engineering', 'Engineering & Technology', 'Civil Engineering', 'Introduces the planning, geometric design, traffic characteristics, pavement materials, and pavement design principles used in transportation systems. The course connects roadway performance with safety, mobility, materials, and design requirements.', 'Develop the ability to analyse transportation requirements and apply engineering principles to roadway planning, geometric design, traffic operations, and pavement systems.', 'Determine sight distance requirements; apply geometric-design principles; analyse basic traffic characteristics; evaluate pavement materials; and apply principles of pavement design.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_015', 'Construction Planning & Management', 'Engineering & Technology', 'Civil Engineering', 'Introduces planning and management methods for construction projects, including project lifecycle planning, scheduling, network analysis, resource allocation, cost control, and construction equipment.', 'Develop competence in planning, scheduling, allocating resources, monitoring costs, and managing construction operations within time, cost, quality, and safety constraints.', 'Prepare project schedules; apply CPM and PERT; allocate and level construction resources; analyse project costs; and select and manage construction equipment.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_016', 'Surveying & Geomatics', 'Engineering & Technology', 'Civil Engineering', 'Introduces principles and field methods for measuring distances, angles, elevations, and positions and for representing spatial information. The course covers errors, levelling, angular surveying, curves, and modern GNSS/GIS-based methods.', 'Develop competence in acquiring, analysing, and representing spatial measurements for engineering planning, mapping, and construction applications.', 'Identify and assess surveying errors; perform levelling; carry out angular measurements; apply curve-setting methods; and explain the use of GNSS/GPS and GIS in engineering surveying.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_017', 'Engineering Thermodynamics', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces thermodynamic properties, systems, control volumes, energy interactions, entropy, and thermodynamic cycles used in engineering analysis. The course develops methods for analysing energy conversion and performance of thermal systems.', 'Develop the ability to apply thermodynamic laws and property relations to analyse closed systems, control volumes, and power cycles.', 'Define thermodynamic states and properties; apply the first and second laws; analyse entropy and exergy; evaluate control-volume processes; and assess ideal-gas power cycles.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_018', 'Fluid Mechanics & Machinery', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces fluid kinematics, conservation laws, viscous-flow behaviour, and the operating principles of hydraulic turbines and pumps. The course develops analytical and performance concepts for fluid machinery and flow systems.', 'Develop competence in applying fluid-mechanics principles to analyse internal flows and evaluate the operation and performance of hydraulic machinery.', 'Describe fluid motion; apply governing conservation equations; analyse viscous-flow effects and boundary layers; explain hydraulic-turbine operation; and evaluate pump performance.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_019', 'Kinematics of Machinery', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces the motion and geometric relationships of mechanisms and machine components, including mechanism analysis, velocity and acceleration, cams, gears, and friction. The course develops methods for analysing machine motion without focusing on force dynamics.', 'Develop the ability to analyse mechanism motion and apply kinematic principles to machine components and mechanisms.', 'Classify and analyse mechanisms; determine velocities and accelerations; design and analyse cam motion; analyse gear trains; and evaluate friction-related effects in mechanisms.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_020', 'Heat and Mass Transfer', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces mechanisms and analytical methods for heat and mass transfer, including conduction, convection, thermal radiation, heat exchangers, and diffusion-based mass transfer. The course links transport mechanisms to thermal-system analysis and design.', 'Develop competence in analysing heat and mass transfer processes and selecting appropriate models for engineering systems.', 'Analyse one-dimensional conduction; evaluate free and forced convection; apply radiation principles; design or analyse heat exchangers; and explain basic mass-transfer mechanisms and rates.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_021', 'Dynamics of Machines', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces dynamic force analysis and vibration of machines, including balancing, free and forced vibration, resonance, and governors and gyroscopes. The course develops methods for predicting and controlling dynamic machine behaviour.', 'Develop the ability to analyse dynamic forces, balancing requirements, and vibration responses in mechanical systems.', 'Determine dynamic forces in mechanisms; analyse balancing conditions; calculate free-vibration characteristics; evaluate forced vibration and resonance; and describe governor and gyroscope functions.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_022', 'Manufacturing Processes', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces major manufacturing processes for producing engineering components, including casting, metal forming, joining, machining, and non-traditional machining. Emphasis is placed on process principles, capabilities, limitations, and applications.', 'Develop understanding of manufacturing-process selection and the relationship between process parameters, materials, product geometry, quality, and production requirements.', 'Explain casting processes; compare forming operations; describe joining methods; analyse basic machining operations; and identify applications and characteristics of non-traditional machining processes.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_023', 'Design of Machine Elements', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces the principles used to design machine elements for strength, stiffness, fatigue life, and reliable service. Topics include failure theories, fatigue, shafts and keys, bearings and springs, and gears.', 'Develop competence in selecting dimensions and materials for machine elements using strength, fatigue, stiffness, and functional requirements.', 'Apply failure theories; design against fatigue; analyse shafts and keys; select and design springs and bearings; and evaluate basic gear-system requirements.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_024', 'Control Systems Engineering', 'Engineering & Technology', 'Mechanical Engineering', 'Introduces mathematical modelling and analysis of dynamic systems and feedback control, including transfer functions, time-domain response, stability, frequency response, and controller design.', 'Develop the ability to model, analyse, assess stability, and design feedback-control systems using standard analytical tools.', 'Develop system models and transfer functions; analyse time response; assess stability using algebraic and frequency-domain methods; interpret frequency-response plots; and design basic feedback controllers.', 'Core', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_025', 'Artificial Intelligence', 'Computer Science', 'Computer Science', 'Artificial Intelligence introduces the computational foundations used to build systems that perceive, reason, learn, plan, and act. It covers intelligent-agent models, state-space and heuristic search, knowledge representation and reasoning, planning and decision making, introductory machine learning, natural-language processing, computer vision, and the engineering concerns that determine whether AI systems are robust, interpretable, safe, and fit for deployment.', 'Develop competence in formulating AI problems, selecting appropriate reasoning and search methods, representing structured knowledge, and evaluating learning- and perception-based systems. Emphasise the relationship between algorithms, representations, uncertainty, system architecture, and responsible deployment.', 'Formulate problems using agent and state-space models; implement and compare search and reasoning methods; represent domain knowledge using logical and graph-based formalisms; explain planning and sequential decision methods; distinguish core AI learning, language, and vision approaches; and evaluate AI systems for performance, robustness, interpretability, fairness, privacy, and safety.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_026', 'Machine Learning', 'Computer Science', 'Computer Science', 'Machine Learning develops the statistical and computational foundations for learning predictive or descriptive models from data. The course covers supervised, unsupervised, semi-supervised, self-supervised, and reinforcement learning; data preparation and feature engineering; regression and classification; probabilistic and Bayesian methods; representation learning; neural networks and deep learning; and rigorous model evaluation and deployment.', 'Develop the ability to construct reproducible machine-learning workflows, choose models appropriate to data and task characteristics, quantify generalisation and uncertainty, and diagnose failure modes such as leakage, imbalance, overfitting, poor calibration, and distribution shift.', 'Prepare and transform data without introducing leakage; formulate regression and classification problems; apply probabilistic, clustering, dimensionality-reduction, and neural-network methods; evaluate models using appropriate validation and performance measures; tune and calibrate models; and design reproducible deployment and monitoring workflows.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_027', 'Distributed Systems', 'Computer Science', 'Computer Science', 'Distributed Systems studies computation in which multiple networked processes cooperate without relying on a single shared state or perfectly synchronised clock. It covers system and failure models, communication and coordination, time and ordering, replication and consistency, distributed transactions and storage, fault tolerance and recovery, scalability, and the architectural trade-offs involved in designing dependable distributed services.', 'Develop the ability to reason about concurrency, partial failure, communication, consistency, and coordination in distributed environments. Emphasise correctness properties, performance trade-offs, fault tolerance, and architectural choices rather than treating distributed systems as simply networked software.', 'Model distributed executions and failure modes; analyse communication and coordination mechanisms; explain replication and consistency models; reason about distributed transactions and storage; design recovery and fault-tolerance mechanisms; and evaluate distributed architectures for correctness, scalability, availability, and performance.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_028', 'Cloud Computing and Virtualization', 'Computer Science', 'Computer Science', 'Cloud Computing and Virtualization examines the abstractions and infrastructure used to deliver compute, storage, networking, and software services as elastic, programmable resources. It covers cloud service and deployment models, hypervisors and virtual machines, containers, resource allocation, storage services, cloud networking, orchestration and automation, security, availability, and operational reliability.', 'Develop an infrastructure-level understanding of how virtualised and cloud resources are provisioned, isolated, scheduled, connected, secured, and monitored. Emphasise elasticity, multi-tenancy, automation, service reliability, and the trade-offs among performance, cost, security, and availability.', 'Differentiate IaaS, PaaS, and SaaS and major cloud deployment models; explain virtual machines and containers; design resource-allocation and storage strategies; analyse cloud networking; describe orchestration and infrastructure automation; and evaluate cloud architectures for security, reliability, scalability, and operational performance.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_029', 'Data Center Operations and Infrastructure', 'Computer Science', 'Computer Science', 'Data Center Operations and Infrastructure examines the physical and digital infrastructure required to operate reliable, high-density computing facilities. It integrates site and rack planning, compute and storage infrastructure, network architecture, electrical distribution and UPS systems, energy-performance measurement, cooling and airflow management, virtualisation, monitoring, capacity planning, redundancy, and emerging infrastructure for accelerated and high-density workloads.', 'Develop systems-level competence in operating and evaluating data-centre infrastructure across IT and facility domains. Emphasise availability, power and thermal constraints, energy efficiency, capacity, maintainability, monitoring, and resilience rather than treating the data centre as a collection of servers.', 'Analyse data-centre layouts and infrastructure dependencies; distinguish IT load from facility load and evaluate power-distribution and UPS arrangements; assess cooling and airflow strategies; evaluate PUE and other operational measures; plan compute, storage, and network capacity; and analyse redundancy, monitoring, reliability, and high-density workload requirements.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_030', 'Concrete Technology', 'Civil Engineering', 'Civil Engineering', 'Concrete Technology examines concrete as an engineered composite material, from constituent materials and cement hydration through mix proportioning, fresh and hardened properties, production, quality control, durability, and special concretes. The course connects material-level mechanisms with mix design, field production, testing, performance, and service-life considerations.', 'Develop the ability to select concrete constituents, proportion mixes, predict and interpret fresh and hardened properties, control production quality, and diagnose durability mechanisms. Emphasise the relationship between composition, processing, microstructure, performance, and exposure conditions.', 'Explain cement hydration and the roles of supplementary cementitious materials, aggregates, water, and admixtures; proportion concrete mixes; evaluate fresh and hardened properties; interpret production and quality-control tests; diagnose durability mechanisms; and select appropriate special concrete technologies for service conditions.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_031', 'Foundation Engineering', 'Civil Engineering', 'Civil Engineering', 'Foundation Engineering applies soil mechanics and site-characterisation principles to the analysis and design of shallow and deep foundations. It covers subsurface investigation, soil parameters, bearing capacity, settlement, foundation-system selection, pile behaviour, construction considerations, and the interaction between ground conditions, structural loads, groundwater, and foundation performance.', 'Develop competence in interpreting site investigation data, selecting representative soil parameters, assessing bearing capacity and settlement, choosing foundation systems, and accounting for construction and ground-condition uncertainties in design.', 'Plan and interpret subsurface investigations; determine design parameters from field and laboratory evidence; analyse shallow-foundation bearing capacity and settlement; evaluate pile and deep-foundation behaviour; select appropriate foundation systems; and identify construction and ground-related risks affecting foundation performance.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_032', 'Water Resources Engineering', 'Civil Engineering', 'Civil Engineering', 'Water Resources Engineering examines the analysis, planning, and management of surface-water and groundwater resources. It covers hydrologic processes, measurement and data analysis, hydrologic modelling, reservoirs and storage, groundwater resources, water-resources systems, and flood and drought management, linking physical water processes with engineering decisions under variability and uncertainty.', 'Develop quantitative understanding of hydrologic systems and the ability to use observations and models for water-resources planning and design. Emphasise storage, allocation, groundwater interaction, extremes, uncertainty, and system-level decision making.', 'Analyse precipitation, infiltration, evaporation, runoff, and watershed processes; interpret hydrologic measurements; formulate and evaluate hydrologic models; analyse reservoir storage and operation; assess groundwater resources; evaluate water-resources systems; and develop engineering responses to floods and droughts.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_033', 'Hydraulics and Hydraulic Engineering', 'Civil Engineering', 'Civil Engineering', 'Hydraulics and Hydraulic Engineering develops the mechanics and design methods used to analyse flowing and static fluids in engineering systems. It covers pressure and hydrostatics, Bernoulli-based energy analysis, pipe and open-channel flow, hydraulic machines, hydraulic structures, transient phenomena such as water hammer, and the integration of components into hydraulic systems.', 'Develop the ability to formulate hydraulic problems from conservation laws and constitutive relations, select appropriate flow models, size and evaluate hydraulic components, and assess transient and system-level behaviour.', 'Apply pressure, continuity, momentum, and energy principles to hydraulic systems; analyse pipe and open-channel flows; evaluate pumps and hydraulic machines; analyse hydraulic structures; assess transient flow and water hammer; and design integrated hydraulic systems subject to performance and operating constraints.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_034', 'Engineering Geology', 'Civil Engineering', 'Civil Engineering', 'Engineering Geology applies geological knowledge to the investigation, design, construction, and risk assessment of infrastructure. It covers minerals and rocks, weathering and geological processes, geological structures and discontinuities, site characterisation, geological hazards, foundation and excavation conditions, and the interpretation of geological information for infrastructure projects.', 'Develop the ability to interpret geological materials and structures in engineering terms, recognise ground-related hazards, and translate geological observations into site and design constraints.', 'Identify and classify engineeringly significant minerals and rocks; interpret weathering and geological processes; characterise discontinuities and site conditions; assess geological hazards; evaluate implications for foundations and excavations; and incorporate geological evidence into infrastructure planning and design.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_035', 'CAD/CAM', 'Mechanical Engineering', 'Mechanical Engineering', 'CAD/CAM integrates digital product definition with computer-aided manufacturing. The course covers geometric and solid modelling, parametric design, engineering graphics, assemblies and design intent, manufacturing planning, CNC programming and machining, computer-aided manufacturing, and the product-data and process links required to move from a digital design to manufacturable output.', 'Develop competence in creating and interrogating digital product models and using them to support manufacturing planning and CNC production. Emphasise geometric validity, design intent, manufacturability, process planning, and data continuity between design and manufacturing systems.', 'Create and evaluate geometric and parametric models; define assemblies and design intent; prepare manufacturing plans; develop CNC programs and machining strategies; use CAM systems for process generation; and evaluate CAD/CAM integration and product-data exchange for manufacturability.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_036', 'Mechatronics', 'Mechanical Engineering', 'Mechanical Engineering', 'Mechatronics integrates mechanical systems with sensing, actuation, embedded computation, signal acquisition, and feedback control. The course covers sensors and transducers, motors and drives, embedded controllers, signal conditioning and data acquisition, system modelling and control, mechatronic integration, testing, and reliability.', 'Develop systems-level competence in selecting and integrating sensors, actuators, controllers, and interfaces. Emphasise signal integrity, closed-loop behaviour, embedded implementation, subsystem interactions, testing, and reliability.', 'Select sensors and actuators for specified requirements; condition and acquire measurement signals; implement embedded control functions; model and analyse mechatronic subsystems; integrate sensing, actuation, computation, and mechanics; and verify system performance and reliability through structured testing.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_037', 'Refrigeration and Air Conditioning', 'Mechanical Engineering', 'Mechanical Engineering', 'Refrigeration and Air Conditioning applies thermodynamics and heat-transfer principles to the analysis and design of refrigeration and comfort-conditioning systems. It covers vapour-compression and related cycles, refrigerant properties and environmental considerations, compressors and other components, psychrometrics, cooling-load estimation, system configurations, performance metrics, and diagnostics.', 'Develop the ability to analyse refrigeration cycles and air-conditioning processes, select and size major components, estimate loads, evaluate system performance, and interpret refrigerant and psychrometric behaviour.', 'Analyse refrigeration cycles using thermodynamic property relations; compare refrigerants and account for safety and environmental constraints; evaluate compressors, condensers, expansion devices, and evaporators; perform psychrometric analysis and cooling-load calculations; and diagnose system performance and faults.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_038', 'Internal Combustion Engines', 'Mechanical Engineering', 'Mechanical Engineering', 'Internal Combustion Engines examines the thermodynamic cycles, mechanical components, air and fuel systems, combustion processes, performance, emissions, after-treatment, and control strategies of reciprocating engines. The course links cycle analysis with real engine behaviour, component constraints, combustion efficiency, pollutant formation, and diagnostic measurements.', 'Develop the ability to analyse engine cycles and performance, interpret combustion and emissions behaviour, and evaluate the interaction of mechanical, fuel, air, exhaust, and control subsystems.', 'Analyse Otto, Diesel, and dual-cycle behaviour; explain the function and loading of major engine components; evaluate air and fuel systems; relate combustion processes to efficiency and emissions; interpret performance tests; evaluate after-treatment technologies; and use control and diagnostic information to assess engine operation.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_039', 'Engineering Materials', 'Mechanical Engineering', 'Mechanical Engineering', 'Engineering Materials examines the structure, processing, properties, selection, and failure of materials used in engineering systems. It covers crystalline structure and defects, diffusion and phase transformations, ferrous and non-ferrous alloys, polymers and ceramics, composites, processing routes, material-property relationships, selection criteria, and failure mechanisms.', 'Develop the ability to relate material structure and processing history to mechanical, thermal, electrical, and chemical behaviour, and to select materials for specified service conditions.', 'Explain structure-property relationships and common material defects; analyse ferrous and non-ferrous alloys; compare polymers, ceramics, and composites; relate processing to microstructure and properties; select materials using performance and service requirements; and diagnose common material failure mechanisms.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_040', 'Chemical Process Calculations', 'Chemical Engineering', 'Chemical Engineering', 'Chemical Process Calculations develops the quantitative methods used to formulate and solve material and energy balances for chemical-process systems. It covers units and dimensions, process variables, component and total balances, reactive systems, energy balances, combined balances, and process-flow calculations, with emphasis on consistent bases, assumptions, degrees of freedom, and physically meaningful solutions.', 'Develop rigorous balance-solving skills for steady-state and selected unsteady process calculations. Emphasise dimensional consistency, basis selection, independent equations, reaction stoichiometry, thermodynamic property data, and verification of results.', 'Set up dimensionally consistent process calculations; formulate total and component material balances; solve balances involving chemical reactions; perform energy balances; combine material and energy constraints; analyse process flowsheets; and check solutions against conservation laws and physical limits.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_041', 'Fluid Flow and Heat Transfer', 'Chemical Engineering', 'Chemical Engineering', 'Fluid Flow and Heat Transfer integrates momentum and energy transport for engineering systems. It covers fluid properties and flow fundamentals, internal and external flow, boundary layers, dimensional and momentum analysis, heat conduction and convection, heat exchangers, radiation, and coupled thermal systems.', 'Develop the ability to formulate fluid-flow and heat-transfer problems using conservation laws, constitutive relations, and dimensionless analysis, and to select appropriate models for engineering design.', 'Analyse internal and external flows; evaluate pressure losses and boundary-layer behaviour; use momentum and dimensional analysis; solve conduction and convection problems; analyse and design heat exchangers; evaluate radiative transfer; and assess coupled fluid-thermal systems.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_042', 'Mass Transfer Operations', 'Chemical Engineering', 'Chemical Engineering', 'Mass Transfer Operations develops the transport and separation principles used in chemical-process equipment. It covers molecular diffusion, interfacial mass transfer, gas absorption and stripping, distillation, liquid-liquid extraction, humidification and drying, adsorption and membrane separation, and the design and evaluation of mass-transfer equipment.', 'Develop competence in selecting and analysing separation operations from phase-equilibrium, mass-transfer, and process requirements. Emphasise operating lines, transfer coefficients, stagewise and differential contact, equipment choice, and design trade-offs.', 'Apply diffusion and mass-transfer relations; analyse absorption, stripping, and distillation systems; evaluate liquid-liquid extraction, humidification, and drying; compare adsorption and membrane separations; determine stage or transfer-unit requirements; and develop preliminary equipment designs.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_043', 'Chemical Reaction Engineering', 'Chemical Engineering', 'Chemical Engineering', 'Chemical Reaction Engineering develops the kinetic and reactor-analysis framework used to convert reaction chemistry into process design. It covers rate laws and parameter estimation, ideal batch/CSTR/PFR models, multiple reactions and selectivity, non-isothermal operation, residence-time distributions, heterogeneous reactions, and reactor design and scale-up.', 'Develop the ability to connect reaction kinetics with reactor performance and design. Emphasise residence time, conversion, selectivity, heat effects, transport limitations, parameter estimation, and scale-up constraints.', 'Estimate and interpret kinetic parameters; analyse ideal batch, CSTR, and PFR behaviour; evaluate conversion and selectivity for multiple reactions; analyse non-isothermal reactors; use residence-time information to assess performance; account for heterogeneous effects; and develop reactor design and scale-up calculations.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_044', 'Process Control and Instrumentation', 'Chemical Engineering', 'Chemical Engineering', 'Process Control and Instrumentation integrates measurement, final control, process dynamics, feedback control, controller tuning, advanced control, and industrial control architecture. It distinguishes the measurement chain from control computation and final actuation, and connects control-loop analysis with PLC, DCS, SCADA, and safety-related industrial systems.', 'Develop the ability to specify and evaluate industrial measurement and control loops, analyse dynamic behaviour, tune controllers, and select control architectures appropriate to process requirements and operational constraints.', 'Select and evaluate process measurements and final control elements; formulate process dynamic models; analyse feedback-loop behaviour; tune PID controllers; evaluate advanced control approaches; and distinguish the roles of PLC, DCS, SCADA, and safety-instrumented functions in industrial automation.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_045', 'Electrical Machines', 'Electrical Engineering', 'Electrical Engineering', 'Electrical Machines develops the electromagnetic and electromechanical principles used to analyse transformers and rotating electrical machines. It covers magnetic circuits, induced EMF and torque production, transformers, DC machines, induction machines, synchronous machines, performance testing, losses, efficiency, and machine applications and drives.', 'Develop the ability to derive and use machine models, interpret operating characteristics, evaluate losses and efficiency, and select machines for specified electrical and mechanical duties.', 'Analyse magnetic circuits and electromechanical energy conversion; derive and use transformer and machine equivalent models; evaluate DC, induction, and synchronous machines; interpret performance and test results; quantify losses and efficiency; and select machines for applications and drive systems.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_046', 'Power Systems', 'Electrical Engineering', 'Electrical Engineering', 'Power Systems examines the generation, transmission, distribution, protection, operation, and stability of electric-power networks. It covers system components and models, transmission and distribution, per-unit representation, power-flow analysis, fault calculations, protection, stability, operational control, and emerging grid architectures.', 'Develop competence in modelling power networks and evaluating steady-state, fault, protection, and dynamic behaviour. Emphasise system security, reliability, voltage and frequency constraints, and the changing architecture of modern grids.', 'Build network models and use the per-unit system; perform power-flow studies; analyse symmetrical and selected unsymmetrical faults; explain protection-system principles; assess transient and steady-state stability; and evaluate operational and emerging-grid requirements.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_047', 'Power Electronics', 'Electrical Engineering', 'Electrical Engineering', 'Power Electronics studies the controlled conversion and conditioning of electrical power using semiconductor switches and converter topologies. It covers power devices, rectifiers, DC-DC converters, inverters, PWM and switching control, commutation, power quality, thermal constraints, and applications such as drives and power supplies.', 'Develop the ability to select converter topologies, analyse switching waveforms and device stresses, design basic control strategies, and evaluate efficiency, power quality, thermal behaviour, and application constraints.', 'Explain the operation and limitations of major power semiconductor devices; analyse rectifier, DC-DC, and inverter topologies; evaluate PWM and switching strategies; assess device losses, thermal constraints, and power quality; and select converter architectures for practical applications.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_048', 'Electrical Measurements and Instrumentation', 'Electrical Engineering', 'Electrical Engineering', 'Electrical Measurements and Instrumentation develops the principles and practices used to acquire trustworthy electrical measurements. It covers measurement errors and performance characteristics, electrical instruments, sensors and transducers, signal conditioning and data acquisition, calibration, uncertainty and statistical evaluation, and instrumentation applications.', 'Develop competence in selecting measurement systems, interpreting instrument specifications, designing signal-conditioning chains, evaluating calibration and traceability, and quantifying uncertainty rather than reporting measurements without an uncertainty basis.', 'Distinguish accuracy, precision, resolution, and major error mechanisms; select and apply electrical instruments and transducers; design signal-conditioning and data-acquisition paths; interpret calibration results; estimate measurement uncertainty statistically; and evaluate instrumentation systems for specified applications.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_049', 'Signals and Systems', 'Electrical Engineering', 'Electrical Engineering', 'Signals and Systems develops mathematical methods for representing and analysing continuous- and discrete-time signals and linear systems. It covers signal transformations, energy and power, linear time-invariant systems, convolution, Fourier analysis, Laplace transforms, Z transforms, sampling and reconstruction, and system characterisation.', 'Develop the ability to move between time- and transform-domain representations, derive system responses, and interpret the implications of linearity, time invariance, stability, frequency content, and sampling.', 'Represent and classify signals; analyse LTI systems using convolution and impulse responses; use Fourier, Laplace, and Z-transform methods; analyse discrete-time systems; evaluate sampling and reconstruction; and characterise systems in time and frequency domains.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active'), ('COURSE_050', 'Environmental Law and Environmental Governance', 'Law', 'Law', 'Environmental Law and Environmental Governance examines the legal principles, institutions, regulatory mechanisms, liability regimes, adjudicatory processes, and governance practices used to prevent and manage environmental harm. It covers environmental rights and principles, regulatory authority, pollution control, liability and enforcement, natural-resource governance, environmental adjudication, and institutional implementation.', 'Develop the ability to identify applicable legal principles and institutional responsibilities, analyse regulatory decisions and liability, and evaluate how environmental governance mechanisms operate in practice. Jurisdiction-specific rules should be supplied and validated separately when the repository is deployed for a particular legal system.', 'Explain major environmental-law principles and institutional arrangements; analyse regulatory and pollution-control mechanisms; assess liability and enforcement issues; evaluate natural-resource governance; interpret environmental adjudication and remedies; and critically assess governance arrangements in context.', 'Core Technical', 'Suggested advanced undergraduate / postgraduate', 'Active') ON CONFLICT DO NOTHING;